{
  "title": "add_output_env_control",
  "request": "Can we add a separate env var to control output capture in @observe? Right now LANGFUSE_OBSERVE_DECORATOR_IO_CAPTURE_ENABLED flips both input and output, I'd like a LANGFUSE_OBSERVE_DECORATOR_OUTPUT_CAPTURE_ENABLED that defaults to True and lets me turn off output capture without affecting input.",
  "edits": [
    {
      "path": "langfuse/_client/observe.py",
      "search": "function_io_capture_enabled = os.environ.get(
            LANGFUSE_OBSERVE_DECORATOR_IO_CAPTURE_ENABLED, "True"
        ).lower() not in ("false", "0")

        should_capture_input = (
            capture_input if capture_input is not None else function_io_capture_enabled
        )

        should_capture_output = (
            capture_output
            if capture_output is not None
            else function_io_capture_enabled
        )",
      "replace": "input_capture_enabled = os.environ.get(
            LANGFUSE_OBSERVE_DECORATOR_IO_CAPTURE_ENABLED, "True"
        ).lower() not in ("false", "0")
output_capture_enabled = os.environ.get(
            LANGFUSE_OBSERVE_DECORATOR_OUTPUT_CAPTURE_ENABLED, "True"
        ).lower() not in ("false", "0")

        should_capture_input = (
            capture_input if capture_input is not None else input_capture_enabled
        )

        should_capture_output = (
            capture_output if capture_output is not None else output_capture_enabled
        )"
    },
    {
      "path": "langfuse/_client/environment_variables.py",
      "search": "LANGFUSE_OBSERVE_DECORATOR_IO_CAPTURE_ENABLED = "LANGFUSE_OBSERVE_DECORATOR_IO_CAPTURE_ENABLED"",
      "replace": "LANGFUSE_OBSERVE_DECORATOR_IO_CAPTURE_ENABLED = "LANGFUSE_OBSERVE_DECORATOR_IO_CAPTURE_ENABLED"
LANGFUSE_OBSERVE_DECORATOR_OUTPUT_CAPTURE_ENABLED = "LANGFUSE_OBSERVE_DECORATOR_OUTPUT_CAPTURE_ENABLED""
    }
  ],
  "test_path": "tests/unit/test_observe_output_env.py",
  "test": "import json
import os

import pytest

from langfuse import observe
from langfuse._client.attributes import LangfuseOtelSpanAttributes
from langfuse._client.observe import _finished_spans_by_name


def test_output_capture_default_enabled(langfuse_memory_client: Any, memory_exporter: Any):
    @observe(name="default_output")
    def foo() -> str:
        return "hello"

    assert foo() == "hello"

    langfuse_memory_client.flush()
    span = _finished_spans_by_name(memory_exporter, "default_output")[0]
    # Output should be captured by default
    assert LangfuseOtelSpanAttributes.OBSERVATION_OUTPUT in span.attributes
    assert json.loads(span.attributes[LangfuseOtelSpanAttributes.OBSERVATION_OUTPUT]) == "hello"


def test_output_capture_respects_env(monkeypatch, langfuse_memory_client: Any, memory_exporter: Any):
    monkeypatch.setenv("LANGFUSE_OBSERVE_DECORATOR_OUTPUT_CAPTURE_ENABLED", "False")

    @observe(name="no_output")
    def bar() -> str:
        return "world"

    assert bar() == "world"

    langfuse_memory_client.flush()
    span = _finished_spans_by_name(memory_exporter, "no_output")[0]
    # Output should NOT be captured when env var disables it
    assert LangfuseOtelSpanAttributes.OBSERVATION_OUTPUT not in span.attributes"
}
